import json,os,pathlib,signal,subprocess,sys,time,urllib.request
r=pathlib.Path(__file__).resolve().parent
args=json.loads((r/'launch-argv.json').read_text())
env=dict(os.environ,DYN_FILE_KV=str(r/'discovery'),PYTHONUNBUFFERED='1')
processes=[]
def launch(arm,module,argv,label):
 log=(r/(label+'.log')).open('w')
 p=subprocess.Popen([sys.executable,str(r/'bootstrap.py'),arm,module,*argv],env=env,cwd=r,stdout=log,stderr=subprocess.STDOUT,start_new_session=True)
 processes.append((p,log));return p

def stop(p):
 if p.poll() is None:
  os.killpg(p.pid,signal.SIGTERM)
  try:p.wait(timeout=15)
  except subprocess.TimeoutExpired:os.killpg(p.pid,signal.SIGKILL);p.wait(timeout=5)

def wait_model(worker,frontend):
 deadline=time.monotonic()+360
 while time.monotonic()<deadline:
  if worker.poll() is not None or frontend.poll() is not None:raise RuntimeError('worker/frontend exited before model registration')
  try:
   with urllib.request.urlopen('http://127.0.0.1:8000/v1/models',timeout=2) as response:
    data=json.load(response)
   if any(m['id']=='Qwen/Qwen3-0.6B' for m in data.get('data',[])):return
  except Exception:pass
  time.sleep(2)
 raise TimeoutError('model registration exceeded360s')

def terminate(signum,frame):raise SystemExit(128+signum)
signal.signal(signal.SIGTERM,terminate)
try:
 worker=launch('baseline','dynamo.sglang',args['worker'],'worker')
 for pair,order in enumerate([['baseline','candidate']],1):
  for arm in order:
   frontend=launch(arm,'dynamo.frontend',args['frontend'],arm+'-frontend')
   try:
    wait_model(worker,frontend)
    output=r/(arm+'-results.json')
    command=[sys.executable,str(r/'future_signature_http.py'),'--url','http://127.0.0.1:8000','--model','Qwen/Qwen3-0.6B','--corpus',str(r/'gpu-corpus.json'),'--arm',arm,'--pair',str(pair),'--repetitions','1','--output',str(output)]
    result=subprocess.run(command,cwd=r,env=env,timeout=240,capture_output=True,text=True)
    (r/(arm+'-client.log')).write_text(result.stdout+result.stderr)
    if output.exists():print('GENERATION_JSON='+output.read_text().replace('\n',''),flush=True)
    result.check_returncode()
   finally:stop(frontend)
 print('GENERATION_COMPLETE=true',flush=True)
finally:
 for p,log in reversed(processes):
  stop(p);log.close()
 for log in sorted(r.glob('*.log')):print('PROCESS_LOG='+log.name+'\n'+log.read_text(),flush=True)

